select content.*
from pro_position_content content
left join position_info position_info on position_info.id = content.position_id
where  position_info.task_state=0
     and content.type = #{type}
     and content.item_code = #{itemCode}
     and position_info.inven_state = #{invenState}
     and content.pallet_state = #{palletState}
limit 1

select content.*
from pro_position_content content
left join position_info position_info on position_info.id = content.position_id
where  position_info.task_state=0 and content.type in

    #{type}

 and content.item_code = #{itemCode}
 and position_info.inven_state = #{invenState}
 and content.pallet_state = #{palletState}
limit 1

select content.*
,position_info.name

,position_info.ware_name
,position_info.inven_state
,position_info.task_state
,position_info.disable_state
,item_type.name as item_type_name
,pro_line.name as line_name
,item_info.item_name as item_name
from pro_position_content content
left join pro_line pro_line on pro_line.code = content.pro_line_code
left join position_info on position_info.id = content.position_id
left join item_type on content.item_type_code = item_type.code
left join item_info on item_info.item_code = content.item_code


     and pro_line.id = #{lineId}
     and pro_line.code = #{proLineCode}
     and content.type = #{type}
     and content.code_group = #{codeGroup}
     and position_info.code = #{code}
     and product_id = #{productId}
     and content.item_type_code = #{itemTypeCode}
     and content.item_code = #{itemCode}
     and position_id = #{positionId}
     and content.pro_line_code = #{proLineCode}
     and pro_process_id = #{proProcessId}
     and device_code = #{deviceCode}
     and device_scan_code_address = #{deviceScanCodeAddress}
     and devce_guangdian_address = #{devceGuangdianAddress}
     and wifi_mode_ip = #{wifiModeIp}
     and wifi_mode_port = #{wifiModePort}
     and pallet_code = #{palletCode}
     and content.ware_code = #{wareCode}

order by content.type , content.code

